{
  "hypotheses": [
    {
      "id": "h1",
      "description": "Identify the actors who appeared in 'The Matrix' (assuming a movie title or context is available to filter by).",
      "details": {
        "type": "Filtering",
        "filter_field": "movie_title",
        "filter_value": "The Matrix"
      }
    },
    {
      "id": "h2",
      "description": "For the identified actors, count the total number of movies they appeared in.",
      "details": {
        "type": "Aggregation",
        "field": "actor_id",
        "aggregation": "COUNT(movie_id)"
      }
    },
    {
      "id": "h3",
      "description": "Find the top 3 actors based on the count from h2.",
      "details": {
        "type": "Ranking",
        "field": "count",
        "limit": 3
      }
    }
  ],
  "query": {
    "type": "JOIN_AND_AGGREGATE",
    "steps": [
      {
        "step_name": "Filter_Matrix_Actors",
        "action": "JOIN",
        "tables": ["Actors", "Movie_Cast"],
        "on": "Actors.actor_id = Movie_Cast.actor_id",
        "filter": {
          "field": "Movie_Cast.movie_title",
          "operator": "=",
          "value": "The Matrix"
        },
        "output_alias": "Matrix_Actors_List"
      },
      {
        "step_name": "Count_Total_Appearances",
        "action": "JOIN",
        "tables": ["Matrix_Actors_List", "Movie_Cast"],
        "on": "Matrix_Actors_List.actor_id = Movie_Cast.actor_id",
        "group_by": ["Matrix_Actors_List.actor_id", "Matrix_Actors_List.actor_name"],
        "aggregate": {
          "field": "Movie_Cast.movie_id",
          "function": "COUNT",
          "alias": "total_appearances"
        },
        "output_alias": "Actor_Counts"
      },
      {
        "step_name": "Rank_Top_Three",
        "action": "ORDER_AND_LIMIT",
        "input_alias": "Actor_Counts",
        "order_by": {
